-- Removes the em dash from did_you_know_facts.fact_text (trivia shown on
-- the Home screen and species detail Overview tab), replacing it per-sentence
-- with whichever of comma / period / parentheses / semicolon reads most
-- naturally. Purely a punctuation rewrite; no facts or wording substance
-- changed. Part of the same house-wide em-dash cleanup as
-- care_field_em_dash_cleanup.sql and ornamental_planting_advice.sql.
--
-- Run via:
--   npx supabase db query --linked < supabase/em_dash_cleanup_facts.sql

UPDATE did_you_know_facts SET fact_text = 'The trifoliate (three-part) leaf structure of Vitex trifolia is immediately diagnostic; no other common campus shrub produces leaves with exactly three distinctly shaped leaflets.' WHERE id = '01880282-05eb-4608-8c09-4897267bb401';
UPDATE did_you_know_facts SET fact_text = 'Vitex trifolia leaves have a distinctive eucalyptus-like scent when crushed, caused by the presence of volatile terpenes (the same aromatic compounds that deter some insect pests).' WHERE id = '02441fd5-3755-41ce-947f-0515a618f3fa';
UPDATE did_you_know_facts SET fact_text = 'Ylang-ylang is one of the fastest-growing trees in the tropics, capable of reaching 5 metres in its first year under ideal conditions, making it one of the quickest paths from seedling to fragrant flowers.' WHERE id = '02e9295a-54da-4967-b6ff-8e4cd850d3b3';
UPDATE did_you_know_facts SET fact_text = 'Avocados contain more potassium per gram than bananas (a fact rarely mentioned in popular nutrition guides). They are also one of the only fruits that is a significant source of monounsaturated fat.' WHERE id = '03a48022-91bd-4d8a-963b-d3811446c9f6';
UPDATE did_you_know_facts SET fact_text = 'Spathodea campanulata nectar is toxic to Australia''s native stingless bees (Lipotriches species), a sobering example of how a plant that is ecologically harmless in its native range can become damaging when introduced elsewhere.' WHERE id = '057f03db-9b3f-45e5-8d52-e94f88b0c5ac';
UPDATE did_you_know_facts SET fact_text = 'Despite being common across Ghana''s secondary forest edges, Alchornea cordifolia remains relatively little-studied pharmacologically compared to its frequency of use in traditional medicine; it is one of the plants that ethnobotanical surveys consistently flag as a research priority.' WHERE id = '06db2a7a-0da4-4718-b2fb-b8fdb641e887';
UPDATE did_you_know_facts SET fact_text = 'Nerium oleander is one of the most toxic ornamental plants in the world; a single leaf contains enough cardiac glycosides to cause serious illness in an adult human, and smoke from burning the wood is also dangerous to inhale.' WHERE id = '075191ae-a238-4427-bc34-ebb00230b347';
UPDATE did_you_know_facts SET fact_text = 'Norfolk Island Pine grows perfectly symmetrically, with exactly six branches per tier, each tier spaced the same distance apart, in a pattern so regular that early European sailors used it as a navigation landmark when approaching Norfolk Island.' WHERE id = '0796b5d0-dd52-4e6d-a2d9-2c3c6ee2b21c';
UPDATE did_you_know_facts SET fact_text = 'Gliricidia sepium can fix up to 100 kg of atmospheric nitrogen per hectare per year, making it one of the most nitrogen-productive trees in tropical agroforestry.' WHERE id = '09e7f70f-effd-40bf-b5c6-4ad64c3cb951';
UPDATE did_you_know_facts SET fact_text = 'Syzygium jambos fruit has a distinctive rose-like fragrance caused by geraniol and other terpenes; despite being a fruit, it smells more like a rose than many actual roses do.' WHERE id = '0cb9e901-04bd-482d-aa4f-9420b30a6be9';
UPDATE did_you_know_facts SET fact_text = 'Red palm oil contains the highest concentration of beta-carotene (pro-vitamin A) of any plant food; it is a critical source of vitamin A in Ghana''s Brong-Ahafo region where vitamin A deficiency affects young children.' WHERE id = '0fb88ee7-ed17-46ec-99ec-c7be13b51d03';
UPDATE did_you_know_facts SET fact_text = 'Ixora coccinea is the official flower of Suriname, and is culturally significant across SE Asia and South Asia as an offering flower in Hindu temples; millions of blooms are used in religious ceremonies daily across India.' WHERE id = '0fdf12b9-5847-41fc-9ac5-5c4b353fc1be';
UPDATE did_you_know_facts SET fact_text = 'The common name Woman’s Tongue comes from the seed pods of Albizia lebbeck; when dry, the large flat papery pods rattle persistently in the wind, producing a constant chattering sound.' WHERE id = '10075e03-30a1-470f-9fe1-968ae3396ed4';
UPDATE did_you_know_facts SET fact_text = 'Calotropis procera is the primary larval host plant for the African monarch butterfly (Danaus chrysippus) in West Africa; removing it from campus would reduce the monarch butterfly population in the area.' WHERE id = '107d7d09-bc5d-4250-bac7-84014e3bd5d3';
UPDATE did_you_know_facts SET fact_text = 'Ficus exasperata leaves are so rough from tiny calcium carbonate cystoliths on their surface that they were traditionally used as a natural sandpaper to smooth wood, clean cooking pots, and remove calluses (functional without being manufactured).' WHERE id = '10f694c2-d29a-4272-a395-73599a343dab';
UPDATE did_you_know_facts SET fact_text = 'The common name ''Moses in the cradle'' refers to the small white flowers nestled inside a boat-shaped purple bract, the flowers representing Moses as a baby, the purple bract representing the basket of bulrushes in which he was hidden, according to the biblical story.' WHERE id = '157b3e08-dbb8-41ad-aab3-ba54eb945d17';
UPDATE did_you_know_facts SET fact_text = 'Despite belonging to the mint family (Lamiaceae), Gmelina is a large tropical tree with no mint scent, a good reminder that plant family membership is determined by flower structure, not smell.' WHERE id = '1699c9ed-e571-4825-a052-86d4c1b4a70a';
UPDATE did_you_know_facts SET fact_text = 'Endophytic fungi isolated from Terminalia mantaly bark have shown potent inhibitory activity against bacteria responsible for pneumonia in laboratory studies, suggesting the tree''s medicinal reputation in Cameroon and Madagascar has a pharmacological basis.' WHERE id = '19301dac-5929-4b46-8503-8eb3cb6dd8a3';
UPDATE did_you_know_facts SET fact_text = 'Siamese Cassia is one of Ghana''s most widely planted street trees; its fast growth, tolerance of poor soils, and dense shade make it ideal for roadside and campus planting.' WHERE id = '1a5edb97-bfd7-4323-a349-ddcdfde7e8ec';
UPDATE did_you_know_facts SET fact_text = 'Dracaena trifasciata is one of the few plants on this list that is truly native to West Africa; its native range extends from Nigeria to the Democratic Republic of Congo.' WHERE id = '1ac1fd17-2983-485f-8d78-b69e704bf2e3';
UPDATE did_you_know_facts SET fact_text = 'Bambusa vulgaris can grow up to 30 cm per day during peak growing season, making it one of the fastest-growing plants on Earth. Unlike trees, each culm reaches its full height in a single growing season, adding no more height in subsequent years.' WHERE id = '1af60532-923b-4075-a3bb-ae78bcf2ef6f';
UPDATE did_you_know_facts SET fact_text = 'Enterolobium cyclocarpum is the national tree of Costa Rica and one of the largest trees in Central America; individual specimens can live for several hundred years and develop trunks over 3 metres in diameter.' WHERE id = '1bed8f73-9fe9-41d1-a771-6c7a6c91bf01';
UPDATE did_you_know_facts SET fact_text = 'Leucaena leucocephala can fix up to 500 kg of atmospheric nitrogen per hectare per year in optimal conditions, making it one of the most nitrogen-productive trees ever measured.' WHERE id = '1c6a2181-2fb2-4496-bd1b-bf46a718fec2';
UPDATE did_you_know_facts SET fact_text = 'The vivid purple underside of Tradescantia spathacea leaves serves a functional purpose; the purple pigment (anthocyanin) reflects infrared radiation, helping the lower leaf surface absorb more light in low-light understorey environments.' WHERE id = '1c740215-6f3a-4ba9-8a54-a421dee37e89';
UPDATE did_you_know_facts SET fact_text = 'Moringa seeds can purify water; when crushed and added to turbid water, they cause suspended particles and bacteria to clump together and settle out, a technique used for water purification in rural Ghana without any chemical treatment.' WHERE id = '1cef572d-10a1-4707-9408-86820a2fcc74';
UPDATE did_you_know_facts SET fact_text = 'Papaya can produce fruit as early as 6–9 months after planting (one of the fastest fruit-producing trees in the tropics).' WHERE id = '1e0d8bc7-1c27-4539-99a6-cd3907eeffc8';
UPDATE did_you_know_facts SET fact_text = 'Croton leaves produce their richest and most vivid colour in direct sunlight; those grown in shade tend to fade toward green, making sunny positions essential for ornamental use.' WHERE id = '204f9e2e-1381-4398-b7c4-d5bad07ea722';
UPDATE did_you_know_facts SET fact_text = 'Gmelina arborea is one of the fastest-growing tropical timber trees; under good conditions it can grow more than 5 metres per year, making it a preferred choice for quick-rotation timber plantations in Ghana.' WHERE id = '20680320-9d00-4d83-a29c-4c16edc714c1';
UPDATE did_you_know_facts SET fact_text = 'After flowering, Furcraea foetida dies, but it typically produces hundreds of bulbils (miniature plantlets) on its massive 7.5 m flower spike before doing so, ensuring its propagation without seeds.' WHERE id = '219f431d-c6f0-4246-b82c-44c66fee960d';
UPDATE did_you_know_facts SET fact_text = 'Like legumes, Casuarina can fix atmospheric nitrogen through root nodule symbiosis, but its partner is not Rhizobium bacteria (as in legumes) but Frankia, a filamentous soil bacterium found in almost no other plant family.' WHERE id = '230a7730-9eef-488c-b51e-e3c97fd5a249';
UPDATE did_you_know_facts SET fact_text = 'Cereus repandus is one of the few cactus species that grows successfully in Ghana''s tropical climate; most cacti are native to the Americas and find humid tropical conditions difficult.' WHERE id = '23d7bab8-71e8-44ba-84c9-9dfcf24170ea';
UPDATE did_you_know_facts SET fact_text = 'Araucaria heterophylla is not a true pine at all; it belongs to the ancient Araucariaceae family, which predates the evolution of true pine trees by over 200 million years and was widespread in the dinosaur era.' WHERE id = '24adc05c-6028-4e36-bc04-431976860acb';
UPDATE did_you_know_facts SET fact_text = 'The seeds of Canna indica are perfectly round, extremely hard, and nearly uniform in size; they were historically used as the shot in early firearms and rattles in musical instruments, giving the plant its name Indian Shot.' WHERE id = '24c6e177-50dd-4b59-b4ef-daeca79648ec';
UPDATE did_you_know_facts SET fact_text = 'Ixora coccinea requires slightly acid soil to absorb iron properly; planted in alkaline or neutral soil, the leaves turn yellow (iron chlorosis) even though iron is present in the soil, because high pH prevents the roots from taking it up.' WHERE id = '25181b90-e183-4f0b-ab26-366b5d10761a';
UPDATE did_you_know_facts SET fact_text = 'The dark brown seed pods of Enterolobium cyclocarpum are shaped exactly like a human ear, 7–9 cm across, making this the most literally named plant in the database.' WHERE id = '2586e1d2-8e17-41be-b8cb-858c3f4467e2';
UPDATE did_you_know_facts SET fact_text = 'The shell of a cashew seed contains a toxic oil called urushiol (same compound found in poison ivy); this is why raw cashews are always processed before sale.' WHERE id = '2638ec78-ee4c-40e7-9923-e5a50982363e';
UPDATE did_you_know_facts SET fact_text = 'Corn silk (the long silky threads inside the husk) is used in Ghanaian traditional medicine as a diuretic and to treat urinary tract infections.' WHERE id = '29ffba53-7945-4f2e-85e0-de1eed8319be';
UPDATE did_you_know_facts SET fact_text = 'Eucalyptus leaves are so resistant to decomposition that they suppress other plants'' growth through allelopathy; allelopathic compounds in the leaf litter prevent seeds from germinating beneath eucalyptus trees, creating a nearly bare forest floor.' WHERE id = '2a2ad982-c4a4-42ab-8421-44f7e33c0b52';
UPDATE did_you_know_facts SET fact_text = 'The cashew ''nut'' is technically a seed that grows outside the cashew apple, a soft pseudofruit, making cashew one of the few plants where the seed grows outside the fruit.' WHERE id = '32e156ad-0dde-417c-863e-f7f46f8dd741';
UPDATE did_you_know_facts SET fact_text = 'The Flamboyant is sometimes called the ''most colourful tree in the world''; when in full bloom in the dry season, the orange-red flowers completely cover the canopy, hiding every leaf.' WHERE id = '33333958-38ce-4fed-981f-f11601610d46';
UPDATE did_you_know_facts SET fact_text = 'Eucalyptus trees are heavy groundwater consumers; large plantations can lower the water table in surrounding agricultural land. Ghana''s Forestry Commission monitors eucalyptus plantations in the Brong-Ahafo region specifically for this water table effect.' WHERE id = '3804243c-3d84-476c-992e-394842ac376e';
UPDATE did_you_know_facts SET fact_text = 'Unlike most conifers, Platycladus orientalis has its scale-like foliage arranged in vertical flat sprays rather than horizontal ones, a diagnostic feature that helps distinguish it from related Thuja species at a glance.' WHERE id = '38862ad5-d15a-4877-9cf8-7287aa760b23';
UPDATE did_you_know_facts SET fact_text = 'Despite being called ''Croton'', this plant is not in the genus Croton; the common name was applied by early botanists who confused it with true Croton species in the same family (Euphorbiaceae).' WHERE id = '3aa571ab-0e54-41e6-bb18-952bfb0161cc';
UPDATE did_you_know_facts SET fact_text = 'Unripe ackee arils contain hypoglycin A, a toxin that causes Jamaican Vomiting Sickness (a potentially fatal hypoglycaemia); the toxin disappears when the fruit naturally splits open, which is why Ghanaian tradition only eats ackee fruit that opens on its own.' WHERE id = '3c942490-ea16-4e80-8506-b48c25ecc291';
UPDATE did_you_know_facts SET fact_text = 'The oil palm is native to West Africa, including Ghana, making it one of the few major global crops that is being grown commercially in its own natural home; most other major oil crops (soybean, rapeseed, sunflower) are grown far outside their places of origin.' WHERE id = '3cde32a7-ee71-44b5-b933-60eae98ba5ce';
UPDATE did_you_know_facts SET fact_text = 'The intense purple colour of Tradescantia pallida comes from anthocyanins (the same pigment family responsible for the colour of red grapes, blueberries, and red cabbage).' WHERE id = '3d60e3e5-a54f-43de-a2ef-6ff4498c9149';
UPDATE did_you_know_facts SET fact_text = 'Voacanga africana seeds are one of the world''s primary pharmaceutical raw materials; voacangine extracted from the seeds is a precursor used in the semi-synthesis of ibogaine, a compound studied for treating opioid addiction.' WHERE id = '3f7306d4-b80a-4f0e-ab27-9d82513b14a6';
UPDATE did_you_know_facts SET fact_text = 'Plumeria flowers are fragrant at night to attract their pollinators (hawk moths) but produce no nectar, essentially deceiving them during pollination.' WHERE id = '404d76e0-5ac7-4a2e-bac5-88cf723a0d6f';
UPDATE did_you_know_facts SET fact_text = 'Caladium tubers can survive completely without leaves for months, entering dormancy during dry periods and re-sprouting when conditions improve, a survival strategy that makes them surprisingly resilient despite their delicate appearance.' WHERE id = '42f4060f-0c16-4a0e-ae78-3abc9f3c8f5e';
UPDATE did_you_know_facts SET fact_text = 'Some studies estimate that a row of mature Mast Trees can absorb up to 27 tonnes of CO₂ per hectare per year, making them among the most carbon-efficient avenue trees in the tropics.' WHERE id = '4450a16a-8b26-4b9f-aa6a-eadbb433288f';
UPDATE did_you_know_facts SET fact_text = 'All parts of Jatropha curcas are toxic, but the seeds are especially dangerous; curcin, the toxic protein in the seeds, acts by the same mechanism as ricin from castor beans, though at lower potency.' WHERE id = '446e39f2-424c-472d-9dda-37be7265fac0';
UPDATE did_you_know_facts SET fact_text = 'Unlike Agave americana, Agave attenuata has no sharp terminal spine on its leaves, making it the only agave safe to plant next to footpaths and seating areas.' WHERE id = '44d848bd-9610-486e-b62e-d07e8261dab7';
UPDATE did_you_know_facts SET fact_text = 'Alchornea cordifolia is one of the top 10 most frequently cited medicinal plants in pharmacological surveys of West African traditional medicine; its leaves, bark, and roots are used to treat more conditions than almost any other single plant across the region.' WHERE id = '4c601cf2-60de-4776-af4f-24130de5f878';
UPDATE did_you_know_facts SET fact_text = 'The nut inside Terminalia catappa fruit is edible and nutritious, tasting similar to an almond, yet in most countries where the tree grows, the nuts go almost entirely unharvested because the outer fruit flesh is not tasty.' WHERE id = '5188b1e3-cf30-4953-99a0-730579dd23d5';
UPDATE did_you_know_facts SET fact_text = 'The Boundary Tree has profound cultural significance across West Africa; uprooting or cutting one without permission is considered a serious breach of customary law in many Ghanaian communities.' WHERE id = '54eaf885-4c1a-4ff1-bc46-e644f2ea4b7e';
UPDATE did_you_know_facts SET fact_text = 'Pongamia pinnata is one of very few non-edible oil trees that can be grown on saline, waterlogged soils where food crops fail, making it a candidate for bioenergy production on marginal land across Ghana''s coastal zones.' WHERE id = '554129fa-8bbb-4a3b-b1c7-52f59d37339e';
UPDATE did_you_know_facts SET fact_text = 'Mimosa pudica is one of only a handful of plants that demonstrate thigmonasty (rapid movement in response to touch), caused by changes in turgor pressure in specialised cells at the leaf joint, not by electrical signals.' WHERE id = '57b86746-fd21-4c54-9bff-eec1c87ccdc1';
UPDATE did_you_know_facts SET fact_text = 'Euphorbia milii has been cultivated for so long in human gardens that its exact wild origin is uncertain; it was possibly extinct in the wild of Madagascar before botanists realised it had one.' WHERE id = '596f863e-bf32-4969-9e83-e002877f3988';
UPDATE did_you_know_facts SET fact_text = 'In Hawaiian culture, Ti Plant (Cordyline fruticosa) is considered sacred; it was planted around homes for spiritual protection, and hula dancers traditionally wore skirts made from its leaves.' WHERE id = '5c8d2e36-998a-448a-8b83-a258c603d23e';
UPDATE did_you_know_facts SET fact_text = 'Every part of the coconut palm has a documented use. Fruit, shell, husk, frond, trunk, and sap each support separate traditional industries; in some coastal Ghanaian communities, the coconut palm is described as providing ''everything a family needs''.' WHERE id = '5d6f9807-b9c3-4ac0-9106-d68eaf489f01';
UPDATE did_you_know_facts SET fact_text = 'Terminalia mantaly''s distinctive tiered horizontal branching is not random; each tier grows in a different compass direction, maximising light capture for every layer of the canopy without individual branches shading each other.' WHERE id = '60588c90-6bca-4c26-8598-231bde8938c9';
UPDATE did_you_know_facts SET fact_text = 'Originally classified as Polyalthia longifolia, the Mast Tree was reclassified to the genus Monoon in 2022 following molecular studies, a good reminder that plant names can change.' WHERE id = '635d3e27-461c-4c69-a889-233c6558600c';
UPDATE did_you_know_facts SET fact_text = 'Almost all commercial 5-HTP supplements sold globally are derived from Griffonia seeds hand-harvested by forest communities in Ghana and Côte d''Ivoire, making it one of Africa''s most economically significant wild plants.' WHERE id = '63c9a89b-e438-4add-b4a1-edc9cedf5a92';
UPDATE did_you_know_facts SET fact_text = 'Gliricidia is widely used as a living fence across Ghana''s Brong-Ahafo Region; stakes cut from branches are simply pushed into the ground and root within weeks, forming a live boundary.' WHERE id = '646825ac-e996-4a70-bf24-8bc80e5c3fdd';
UPDATE did_you_know_facts SET fact_text = 'The flowers of Cereus repandus open only at night and last just a single night; they are pollinated exclusively by nocturnal moths and bats, then close permanently by morning.' WHERE id = '65313a4d-189d-4bea-9283-121f0b542bec';
UPDATE did_you_know_facts SET fact_text = 'Castor oil is used in biodegradable lubricants, hydraulic fluids, cosmetics, and even as a jet engine lubricant (one of the most chemically versatile plant oils known).' WHERE id = '6642281a-1399-4e1d-89a1-75c057470a55';
UPDATE did_you_know_facts SET fact_text = 'The Brong-Ahafo Region (where UENR is located) is one of Ghana''s primary mango-producing zones.' WHERE id = '6acf4f54-a36f-419b-a959-34380c9bc7a0';
UPDATE did_you_know_facts SET fact_text = 'The deep red pigmentation of Alternanthera dentata comes from betacyanins, a pigment class found in only about 13 plant families and responsible for the red colour of beetroots as well, chemically distinct from the anthocyanins that colour most other red plants.' WHERE id = '6bd3fa63-cd1c-4c05-ad7c-ace9b08c311f';
UPDATE did_you_know_facts SET fact_text = 'Tradescantia spathacea is closely related to Purple Heart (Tradescantia pallida), already in the dataset as species #15; both are in the same genus, both share purple pigmentation, but the oyster plant''s purple is on the leaf underside while Purple Heart''s is throughout the leaf.' WHERE id = '701c9b02-b269-429e-93e6-c6a3a21632c2';
UPDATE did_you_know_facts SET fact_text = 'Platycladus orientalis has been cultivated in Chinese gardens for over 3,000 years and is considered a symbol of longevity and resilience in Chinese culture; individual trees in temple gardens are known to survive for centuries.' WHERE id = '70bf3de5-6ced-465c-b742-14164920a829';
UPDATE did_you_know_facts SET fact_text = 'Breynia disticha is classified in the Phyllanthaceae family (formerly lumped into Euphorbiaceae and only separated following molecular studies in the early 2000s).' WHERE id = '71c20b44-5597-480c-9b59-17365cd70849';
UPDATE did_you_know_facts SET fact_text = 'Despite being called Spanish Cedar, Cedrela odorata is not a true cedar (genus Cedrus) at all; the name was applied because its aromatic wood smells similar to true cedars and was used for the same purposes.' WHERE id = '72410533-bab6-4781-b1f8-d4f0024beff7';
UPDATE did_you_know_facts SET fact_text = 'Sphagneticola trilobata is classified by IUCN as one of the world''s 100 worst invasive alien species; once established, it forms dense mats that exclude virtually all native groundcover plants beneath it.' WHERE id = '7af252cd-a2f3-44ee-ae89-57bf95e56a33';
UPDATE did_you_know_facts SET fact_text = 'Casuarina equisetifolia is often called ''Australian pine'' in parts of the Americas, but it is not a true pine at all; it is a flowering plant whose needle-like branchlets evolved independently to look like pine needles.' WHERE id = '7b970c73-fbff-4fc6-8928-71236a84bd65';
UPDATE did_you_know_facts SET fact_text = 'Neem is called the ''village pharmacy'' across West Africa; its bark, leaves, seeds, and oil are used to treat over 40 different health conditions in traditional medicine.' WHERE id = '7e25cfdc-1ecc-48a1-a314-725220014fc8';
UPDATE did_you_know_facts SET fact_text = 'The photosynthetic rate of Sphagneticola trilobata is measurably higher than that of its native West African congener Sphagneticola calendulacea, a key reason the invasive species consistently outcompetes the native one when the two grow together.' WHERE id = '7f79cc69-6e01-471c-a85a-ab9f5c745a7a';
UPDATE did_you_know_facts SET fact_text = 'Bambusa vulgaris was ranked the most culturally significant building plant in Ghana''s Volta Region ethnobotany study, ahead of timber trees, palms, and grasses, confirming how central bamboo is to Ghanaian vernacular construction.' WHERE id = '803089ae-0083-4352-b054-5d427c2d7ca3';
UPDATE did_you_know_facts SET fact_text = 'Codiaeum variegatum has over 100 named cultivars with leaves in virtually every combination of red, yellow, orange, green, and white; the colour variation comes from different concentrations of chlorophyll and anthocyanins.' WHERE id = '81af95e7-dae4-4bbb-96e0-33c44feb3a18';
UPDATE did_you_know_facts SET fact_text = 'Paper Mulberry is considered an invasive species in some ecosystems due to its rapid growth and prolific seeding, a reminder that not all species on campus are ecologically neutral.' WHERE id = '887b50ac-3630-4007-9930-ea0da51215f5';
UPDATE did_you_know_facts SET fact_text = 'Ficus benjamina is one of the most common causes of occupational latex allergy in greenhouses and plant nurseries worldwide; the milky sap can cause skin sensitisation with repeated exposure.' WHERE id = '89bd3b88-4a1e-49a3-aa06-c19b8045fefd';
UPDATE did_you_know_facts SET fact_text = 'The Silktree''s feathery leaves fold up at night and on cloudy days (a behaviour called nyctinasty thought to conserve moisture and protect against cold).' WHERE id = '89e596fb-7cae-4056-8e94-a222c36e426f';
UPDATE did_you_know_facts SET fact_text = 'Albizia lebbeck has spread as an invasive species in Hawaii, Florida, and parts of the Pacific due to its drought tolerance and fast growth, yet in Ghana it is cultivated deliberately as a valuable shade tree for cacao plantations.' WHERE id = '89e853d2-5ebc-464a-907b-f30728989d69';
UPDATE did_you_know_facts SET fact_text = 'Unlike bananas, plantains are starchy and must be cooked; they are harvested and eaten at different stages of ripeness, from firm green (for ampesi) to sweet black-skinned (for kelewele).' WHERE id = '8b75a5d7-8f77-40e4-873a-d23f1b8d5b14';
UPDATE did_you_know_facts SET fact_text = 'Alternanthera dentata is classified in the amaranth family (Amaranthaceae), which also includes spinach, beets, and quinoa, making it a distant relative of several important food crops despite being grown purely as an ornamental.' WHERE id = '8bed7f2f-238b-4a6f-b19f-ec95a95d4a60';
UPDATE did_you_know_facts SET fact_text = 'Avocado is technically an evolutionary orphan; the fruit evolved to be dispersed by now-extinct giant ground sloths and gomphotheres (relatives of elephants). After those megafauna vanished, humans became the only creatures large enough to swallow and disperse the large seed.' WHERE id = '8cf8a8ff-270a-4f4f-8d85-e487dad69c73';
UPDATE did_you_know_facts SET fact_text = 'During the 1970s and 1980s, Leucaena was promoted globally as a ''miracle tree''; it has since been placed on the IUCN''s list of 100 worst invasive species in certain ecosystems, a reminder that the same traits that make a plant valuable can make it ecologically risky.' WHERE id = '8f019605-ac1c-4609-b4ab-713c43e52400';
UPDATE did_you_know_facts SET fact_text = 'Dypsis lutescens is endemic to Madagascar, one of the world''s top biodiversity hotspots, where it is now endangered in the wild, making every cultivated specimen a conservation representative of a threatened species.' WHERE id = '8fea783f-cfee-4c70-997c-cb86d9fa220d';
UPDATE did_you_know_facts SET fact_text = 'Cedrela odorata is listed on CITES Appendix III, meaning international trade in its timber requires export permits, a reflection of how severely over-harvested this premium timber species has been across tropical America.' WHERE id = '906bdb19-de28-4036-a436-fb1d54be2bf9';
UPDATE did_you_know_facts SET fact_text = 'Terminalia mantaly is endemic to Madagascar, one of the world''s top biodiversity hotspots; it is one of over 10,000 plant species found there and nowhere else on Earth.' WHERE id = '9432cccb-08f5-49e3-932a-47bcc2e21408';
UPDATE did_you_know_facts SET fact_text = 'Papaya leaves are used across Ghana in traditional medicine to treat malaria, dengue fever, and platelet disorders, a practice gaining increasing scientific scrutiny.' WHERE id = '94475eae-4f61-41a0-b37e-4a91b40a2e1a';
UPDATE did_you_know_facts SET fact_text = 'A single plantain plant produces one bunch of fruit in its lifetime, then dies back, but shoots (suckers) growing from its base replace it, allowing continuous production.' WHERE id = '96f33064-4be7-495d-9d65-0657b0289585';
UPDATE did_you_know_facts SET fact_text = 'Caladium leaves contain calcium oxalate crystals that cause intense burning and swelling if chewed or if the sap enters the mouth (the same compound found in elephant ear and taro plants). The pain is sometimes described as like swallowing broken glass.' WHERE id = '97a8d48c-450e-434a-82eb-51637e77cf05';
UPDATE did_you_know_facts SET fact_text = 'Orange blossom flowers are among the most fragrant in the plant kingdom; orange blossom water distilled from the flowers is used in traditional Ghanaian and North African cooking.' WHERE id = '981838b7-1491-4c80-a3e4-ce02b66b9ede';
UPDATE did_you_know_facts SET fact_text = 'In Ghanaian markets, dried Prekese pods are sold as both a cooking spice and a medicinal herb simultaneously, reflecting the Akan understanding that food and medicine are not separate categories but part of the same continuum of plant benefit.' WHERE id = '985d6401-3aa9-4954-b23a-92e25a4402d7';
UPDATE did_you_know_facts SET fact_text = 'The distinctive spoon-shaped or ''hammerhead'' leaves of Plumeria pudica are diagnostic; no other Plumeria species produces this unique spatulate leaf shape.' WHERE id = '999b9598-6d91-4a6b-ac1c-a5befaef29d0';
UPDATE did_you_know_facts SET fact_text = 'Vinpocetine, a medication used to treat Alzheimer''s disease and improve cerebral blood flow, is synthesised from voacangine, making Ghana one of the world''s most important sources of an Alzheimer''s treatment precursor.' WHERE id = '9c52c6ff-4026-45dd-9d42-df4f0764240e';
UPDATE did_you_know_facts SET fact_text = 'Hibiscus flower extract has been shown in clinical studies to reduce systolic blood pressure, supporting its traditional use in Ghanaian herbal medicine for cardiovascular conditions.' WHERE id = '9ced2d0a-8ea2-4881-845f-041f630f95e5';
UPDATE did_you_know_facts SET fact_text = 'Gmelina flowers before leafing out, producing yellow-orange tubular flowers on bare branches, an unusual sight that makes the flowering trees look like they are on fire in the dry season.' WHERE id = '9d0b5ac2-cfe2-49d3-8e9b-4bae48bfccfa';
UPDATE did_you_know_facts SET fact_text = 'Syzygium myrtifolium belongs to the largest genus of tropical flowering trees, Syzygium, which contains over 1,200 species including cloves (Syzygium aromaticum), one of the world''s most economically important spices.' WHERE id = '9d18c015-6fff-4396-bb62-ccbac59df4be';
UPDATE did_you_know_facts SET fact_text = 'Despite its extreme toxicity to animals, Oleander is one of the most widely planted ornamental shrubs globally; its drought tolerance, heat resistance, and continuous flowering make it almost irresistible to landscape designers.' WHERE id = '9d4d24ad-f9cd-4a53-a19a-0b2d897828f3';
UPDATE did_you_know_facts SET fact_text = 'Broussonetia papyrifera bark was the traditional source of tapa cloth (a beaten bark fabric used throughout the Pacific Islands for clothing, wrapping, and ceremonial purposes).' WHERE id = '9e9bba84-2ea3-46ee-9f27-6d40f61d774d';
UPDATE did_you_know_facts SET fact_text = 'The Akan name for Voacanga africana is ''Ofruma'', a name that echoes ''ofruntum'', the Akan name for the related rubber tree Funtumia elastica, reflecting the two species'' shared latex-producing Apocynaceae family.' WHERE id = '9edc360b-d3a3-41bf-8871-f62a0b615874';
UPDATE did_you_know_facts SET fact_text = 'Casuarina equisetifolia is one of the primary tree species used to stabilise coastal sand dunes in Senegal, Ghana, and other West African countries; its deep root system and salt tolerance make it uniquely suited to hostile coastal conditions.' WHERE id = '9f6c9228-a773-409d-bfb0-bfc975ebceb2';
UPDATE did_you_know_facts SET fact_text = 'Bamboo culms are hollow but structurally stronger per unit weight than many structural steels in tensile loading, a reason bamboo scaffolding is still used in Hong Kong and parts of West Africa for high-rise construction.' WHERE id = 'a1e367d9-d781-487a-9780-e94ef4dec561';
UPDATE did_you_know_facts SET fact_text = 'Research has shown that Mimosa pudica can learn from repeated non-harmful stimulation; plants that were repeatedly dropped (harmlessly) gradually stopped folding their leaves in response, suggesting a basic form of learned habituation.' WHERE id = 'a9ab030f-b43e-4dfe-a858-f5623c4b4bc4';
UPDATE did_you_know_facts SET fact_text = 'Duranta erecta berries are toxic to humans and pets but are a favourite food of birds; the species uses birds as seed dispersers while maintaining chemical defences against mammals.' WHERE id = 'ada807ea-9f9a-459f-ab6c-5206bf7a9e9f';
UPDATE did_you_know_facts SET fact_text = 'Paper Mulberry is documented at UENR campus in the context of bat seed dispersal; its fleshy fruits are consumed by fruit bats that then disperse seeds throughout the bat sanctuary.' WHERE id = 'aeaf7aa4-7065-45f8-bb08-b3568beadcfa';
UPDATE did_you_know_facts SET fact_text = 'Sphagneticola trilobata reproduces by rooting at stem nodes wherever they touch moist soil; a single plant can spread several metres per season without producing a single seed.' WHERE id = 'afa17f7f-eedd-4a9b-967f-af6b3815bf90';
UPDATE did_you_know_facts SET fact_text = 'Cordyline fruticosa roots are starchy and sweet when cooked; they were a traditional food source across the Pacific Islands, baked in earth ovens for several days to develop sugars.' WHERE id = 'b397d541-0f4c-43f8-947c-1cd15c2871c2';
UPDATE did_you_know_facts SET fact_text = 'Furcraea foetida is regarded as an environmental weed in Western Australia and Queensland, where it escapes cultivation and invades native vegetation, a reminder that an ornamental on one continent can be ecologically damaging on another.' WHERE id = 'b536ab19-923a-4f6b-ab5d-2e0166ecb733';
UPDATE did_you_know_facts SET fact_text = 'Agave attenuata produces an unusual drooping flower spike rather than the upright stalk of most agaves; it hangs downward under its own weight, earning it the name ''foxtail agave''.' WHERE id = 'b6bb8d3d-6526-479b-a48d-534ea98fea82';
UPDATE did_you_know_facts SET fact_text = 'With over 5,000 registered cultivars, Chinese Hibiscus produces flowers in virtually every colour except true blue, making it one of the most diverse ornamental shrubs in the tropics.' WHERE id = 'b72af76c-718c-465d-9eb2-07cf4d829926';
UPDATE did_you_know_facts SET fact_text = 'Eucalyptus is the source of one of the world''s most commercially important essential oils, eucalyptol (1,8-cineole), used in cough syrups, antiseptic mouthwashes, chest rubs, and industrial cleaning products worldwide.' WHERE id = 'b8e299ff-b720-4121-b002-a136b5af9aca';
UPDATE did_you_know_facts SET fact_text = 'Ixora belongs to the coffee family (Rubiaceae), making it a close relative of coffee, quinine, and Morinda lucida, a medicinal tree also common in Ghana.' WHERE id = 'bc8895f1-4647-4813-9a44-52d7ad71fba4';
UPDATE did_you_know_facts SET fact_text = 'With its trailing stems, purple flowers, and golden berries appearing simultaneously, Golden Dewdrop produces three separate ornamental displays at once (flower, fruit, and foliage).' WHERE id = 'c18eea5c-cb5b-4769-9dcc-eea8b8e03046';
UPDATE did_you_know_facts SET fact_text = 'Moringa leaves contain more vitamin C than oranges, more calcium than milk, more potassium than bananas, and more iron than spinach, making the ''miracle tree'' arguably the most nutritionally concentrated food plant that grows in the tropics.' WHERE id = 'c72b65ec-5345-43c1-ba88-fa18facecbe5';
UPDATE did_you_know_facts SET fact_text = 'A coconut husk can keep a coconut seed viable and floating in seawater for over 100 days, long enough for ocean currents to carry it thousands of kilometres between islands, explaining why coconuts colonised Pacific atolls long before humans arrived.' WHERE id = 'c72ebe98-1a13-4060-91e6-efdfb8184fe6';
UPDATE did_you_know_facts SET fact_text = 'The Brong-Ahafo Region (where UENR is located) is one of Ghana''s primary mango-producing zones, making campus trees part of a living agricultural heritage.' WHERE id = 'c786738b-78d1-4f29-be72-3e96f168cfa5';
UPDATE did_you_know_facts SET fact_text = 'Like many fig species, Ficus exasperata can begin life as an epiphyte, germinating on a host tree''s branch and eventually sending down aerial roots that strangle the host, earning figs the informal name ''strangler figs''.' WHERE id = 'c841f484-551a-4d80-aa4c-f21f0e3f5abc';
UPDATE did_you_know_facts SET fact_text = 'All parts of Polyscias fruticosa are mildly toxic to dogs and cats; the saponins in the sap cause gastrointestinal distress and drooling if pets ingest the leaves.' WHERE id = 'c89166e0-f872-48dd-a148-92238081d23d';
UPDATE did_you_know_facts SET fact_text = 'The Mast Tree''s tall, narrow, columnar shape makes it one of the most effective natural sound barriers for roadside planting; its dense foliage absorbs traffic noise.' WHERE id = 'cc58a5bf-e46b-4947-84a6-a63beb8055a1';
UPDATE did_you_know_facts SET fact_text = 'Chinese Banyan can begin life as an epiphyte, germinating on another tree and sending down aerial roots that eventually strangle the host, replacing it entirely.' WHERE id = 'd1725f0d-bc37-450f-8f87-cf131ae014d8';
UPDATE did_you_know_facts SET fact_text = 'Ackee is the national fruit of Jamaica, despite being native to West Africa; Thomas Clark brought the seeds from Ghana to Jamaica in 1776, and the fruit became so culturally embedded in Jamaican cuisine that it became the national dish (ackee and saltfish).' WHERE id = 'd25c13f2-25b3-4abe-92a3-8b3cd11c0962';
UPDATE did_you_know_facts SET fact_text = 'In ancient Rome, Oleander was reportedly used as a poison. It contains oleandrin, a cardiac glycoside that disrupts the heart''s electrical system; even honey made from oleander nectar can be toxic.' WHERE id = 'd27d5305-88b3-4263-be68-20448060c0cb';
UPDATE did_you_know_facts SET fact_text = 'Azadirachtin, a compound extracted from neem seeds, is one of the most effective botanical pesticides known; it disrupts insect development without the toxicity of synthetic pesticides.' WHERE id = 'd3e0a2c1-e42e-41cf-8fab-a2a972a71bbd';
UPDATE did_you_know_facts SET fact_text = 'Griffonia simplicifolia seeds contain up to 20% 5-hydroxytryptophan (5-HTP) by weight, the highest natural concentration known, making Ghana one of the world''s most important sources of a globally traded nutraceutical.' WHERE id = 'd45da9dc-419b-47f9-ad5a-6ed4d659e3fd';
UPDATE did_you_know_facts SET fact_text = 'A single hectare of oil palm produces more edible oil than any other crop (roughly 3.7 tonnes per hectare per year, compared to 0.7 tonnes for rapeseed and 0.5 tonnes for sunflower). This yield efficiency is why it now produces over 35% of the world''s vegetable oil on just 10% of the land devoted to oil crops.' WHERE id = 'd53cc5f6-dd2b-4d6f-85dc-5c24a3fac7c0';
UPDATE did_you_know_facts SET fact_text = 'Syzygium jambos belongs to one of the largest genera of flowering trees; Syzygium contains over 1,200 species, including cloves (Syzygium aromaticum), making it one of the most economically important tropical tree genera.' WHERE id = 'd5bfd2e8-db55-4b7f-af45-332d023fc634';
UPDATE did_you_know_facts SET fact_text = 'The ''water'' inside a young green coconut is one of the most naturally sterile liquids on Earth; during World War II, it was used as an emergency intravenous saline solution when medical supplies ran out in the Pacific.' WHERE id = 'd6ab51f1-de24-4386-af54-0eebff7072bd';
UPDATE did_you_know_facts SET fact_text = 'Each species of Ficus depends on a single unique species of fig wasp for pollination (Ficus microcarpa relies on Eupristina verticillata). Without its wasp, the tree cannot produce fertile seeds.' WHERE id = 'd75c4b30-c837-40fc-b77c-f3456f044cd8';
UPDATE did_you_know_facts SET fact_text = 'The crinkled, crepe paper-like texture of Lagerstroemia flowers is the characteristic that gives the entire Crape-Myrtle genus its name; each petal looks like a tiny piece of crumpled tissue paper.' WHERE id = 'd79e2213-166b-4000-a6d7-9061117af83f';
UPDATE did_you_know_facts SET fact_text = 'Vitex species are used across West Africa and SE Asia in traditional medicine to treat fever, joint pain, and skin inflammation, with scientific studies confirming anti-inflammatory activity.' WHERE id = 'dbb67a6a-a8db-4aa8-8d20-af2ad5b15e86';
UPDATE did_you_know_facts SET fact_text = 'The name ''ylang-ylang'' comes from the Tagalog (Filipino) word ''ilang-ilang'', which is sometimes translated as ''flower of flowers'', though linguists consider this translation disputed.' WHERE id = 'de03927d-7b31-4ac7-a9e6-52bfa00df45c';
UPDATE did_you_know_facts SET fact_text = 'Ylang-ylang essential oil is the dominant fragrance note in Chanel No.5 (the world''s best-selling perfume), making Cananga odorata one of the most commercially important fragrant plants on Earth.' WHERE id = 'e03e7453-6a10-4356-b7ec-55e7bc63d8e6';
UPDATE did_you_know_facts SET fact_text = 'Rose apple has been cultivated in Southeast Asia for so long that its wild origin is now difficult to determine; it is one of several fruit trees that humans have moved so extensively that botanists cannot agree on where it originally evolved.' WHERE id = 'e0c6aaa9-31a2-43e8-a1aa-25b411c8054a';
UPDATE did_you_know_facts SET fact_text = 'The species name ''fruticosa'' means ''shrubby'' in Latin, a straightforward description of its dense, branching, shrub-like growth habit.' WHERE id = 'e42a56e9-dda6-4ea1-b329-b308793b4d12';
UPDATE did_you_know_facts SET fact_text = 'The fleshy fruit, sometimes sold as ''pitaya'' or ''Peruvian apple'', is sweet, nutritious, and edible, surprising for a plant whose stems are so well-armed with spines.' WHERE id = 'e7cb6867-ac6e-4173-b69f-56efb7c542a7';
UPDATE did_you_know_facts SET fact_text = 'Over 1,000 named Caladium cultivars exist, with leaf colours ranging from near-white to deep crimson, pink, orange, and every combination in between; the colour diversity has been achieved through selective breeding of just a handful of wild Amazonian species.' WHERE id = 'eb4141b3-f0aa-4823-9270-990f40cb1018';
UPDATE did_you_know_facts SET fact_text = 'Adonidia merrillii is endemic to the island of Palawan in the Philippines, where it grows in coastal limestone soils, making it naturally adapted to well-drained tropical conditions.' WHERE id = 'eb8cbc7c-837f-4d43-82a4-b6809d516cd7';
UPDATE did_you_know_facts SET fact_text = 'Polyscias fruticosa is one of the most popular bonsai trees in tropical Asia; its slow growth, fine-textured foliage, and tolerance of root pruning make it ideal for the bonsai art form.' WHERE id = 'ebe6196a-24cc-467b-8637-2454490b0b6f';
UPDATE did_you_know_facts SET fact_text = 'The name ''gari'' (Ghana''s beloved dried cassava product) comes from traditional processing that makes cassava safe and shelf-stable for months without refrigeration.' WHERE id = 'ef3b1ae2-d7bc-41c9-bc63-d4598a12a277';
UPDATE did_you_know_facts SET fact_text = 'As a nitrogen-fixing legume, the Silktree enriches the soil beneath it, making it a dual-purpose tree combining ornamental beauty with agricultural soil improvement.' WHERE id = 'f100bcc0-b8dd-4c33-a76b-b94fa19eec6a';
UPDATE did_you_know_facts SET fact_text = 'Despite being native to West Africa, Spathodea campanulata is on the IUCN''s list of 100 worst global invasive species; it escapes from cultivation so readily in the Pacific and Caribbean that it smothers native forest species in those regions.' WHERE id = 'f1ad2581-d18b-45f2-becb-49fffcadb4d4';
UPDATE did_you_know_facts SET fact_text = 'Ricin, extracted from castor beans, is one of the most toxic naturally occurring substances known; as little as a few micrograms per kilogram of body weight can be lethal.' WHERE id = 'f3598e1f-11ff-42b0-a841-60f84690aa6f';
UPDATE did_you_know_facts SET fact_text = 'Aloe vera gel contains over 75 active compounds including vitamins, enzymes, minerals, and polysaccharides, making it one of the most chemically complex plant-derived cosmetic ingredients known.' WHERE id = 'f4aac80c-807f-499d-9806-1bbbed1648c3';
UPDATE did_you_know_facts SET fact_text = 'In the Brong-Ahafo Region, maize forms the foundation of kenkey, banku, and tuo zaafi (three of Ghana''s most culturally significant cooked staple foods).' WHERE id = 'f52547c0-b325-48d5-bf75-524be0897e1a';
UPDATE did_you_know_facts SET fact_text = 'The flower buds of Spathodea campanulata are shaped like ampules and contain water; children across West Africa traditionally play with them by squeezing the buds to squirt water at each other, earning the tree the Ghanaian nickname ''water tree''.' WHERE id = 'f5f00b1c-34b7-4075-98b6-19c298f16aed';
UPDATE did_you_know_facts SET fact_text = 'Ghana''s avocado export industry has grown substantially in the 2020s, with Brong-Ahafo a primary growing region; Ghana is now among the top 10 avocado-exporting countries in Africa.' WHERE id = 'f726e3e6-8573-4692-9c57-3322c1990e82';
UPDATE did_you_know_facts SET fact_text = 'Copperleaf leaves contain tannins and flavonoids that inhibit bacterial growth, making leaf extracts a subject of growing pharmacological research for antimicrobial applications.' WHERE id = 'f770344d-cbbf-49fd-8017-9a7a538327f0';
UPDATE did_you_know_facts SET fact_text = 'Terminalia catappa leaves are used in aquarium keeping worldwide as a natural water conditioner; tannins released from the leaves lower pH, soften water, and provide antimicrobial benefits that mimic the natural habitat of soft-water fish species.' WHERE id = 'f7c0b865-38e6-416b-8ca7-1b51a46ca554';
UPDATE did_you_know_facts SET fact_text = 'Delonix regia is endemic to Madagascar''s dry deciduous forests where it is endangered in the wild, yet it is one of the most widely planted ornamental trees in the tropics, making it the unusual case of a wild-endangered species that is thriving in cultivation.' WHERE id = 'fa3078af-7e8d-42fa-9f1c-624ec7378367';
UPDATE did_you_know_facts SET fact_text = 'Each individual flower of Tradescantia pallida lasts for only one day before closing and being replaced by a new bloom, though the plant flowers continuously throughout the year.' WHERE id = 'fb577ca5-908f-4325-8ed4-6b9292cc9c6a';
UPDATE did_you_know_facts SET fact_text = 'The word ''ackee'' in English comes directly from the Akan Twi name ''akye fufo'' (one of the clearest examples of a West African plant name entering the English language through the transatlantic slave trade).' WHERE id = 'ffd25740-9615-4724-8bb0-89368f6cbc06';
